// Generar respuesta para agendamiento usando Gemini
// Recuperar datos de entrada
const inputData = $input.first().json;
const mensaje = inputData.mensaje || '';
const telefono = inputData.telefono || '';
const nombre = inputData.nombre || '';

// Verificar citas existentes (vienen del nodo anterior)
const citasProximas = $json;
const clienteId = inputData.clienteId || (citasProximas[0] && citasProximas[0].cliente_id) || null;

let respuesta = '';

// Detectar intención del mensaje
const mensajeLower = mensaje.toLowerCase();
const esCancelacion = /cancelar|cancelación|eliminar|borrar|anular/i.test(mensajeLower);
const esReprogramacion = /reprogramar|cambiar|modificar|recorrer|correr/i.test(mensajeLower);
const esAgendamiento = /agendar|agendamiento|programar|reservar|separar/i.test(mensajeLower) || !esCancelacion;

if (esCancelacion && citasProximas && citasProximas.length > 0) {
  respuesta = 'Hola ' + (nombre || '') + ', hemos recibido tu solicitud de cancelación. '
    + 'Tienes ' + citasProximas.length + ' cita(s) próxima(s):\n';
  citasProximas.forEach(function(cita, i) {
    respuesta += (i + 1) + '. ' + cita.fecha + ' a las ' + cita.hora + ' - ' + (cita.servicio || 'Sin especificar') + '\n';
  });
  respuesta += '\nPor favor, indícanos qué cita deseas cancelar para procesarlo.';
} else if (esReprogramacion && citasProximas && citasProximas.length > 0) {
  respuesta = 'Hola ' + (nombre || '') + ', podemos ayudarte a reprogramar tu cita. '
    + 'Actualmente tienes:\n';
  citasProximas.forEach(function(cita, i) {
    respuesta += (i + 1) + '. ' + cita.fecha + ' a las ' + cita.hora + ' - ' + (cita.servicio || 'Sin especificar') + '\n';
  });
  respuesta += '\n¿Qué fecha y hora prefieres para tu nueva cita?';
} else {
  // Nuevo agendamiento
  respuesta = '¡Hola ' + (nombre || '') + '! 😊\n\n'
    + 'Con gusto te ayudamos a agendar tu servicio en *Moto Servicios TIMON*.\n\n'
    + 'Por favor, indícanos:\n'
    + '1️⃣ ¿Qué servicio necesitas? (Ej: cambio de aceite, afinación, revisión general)\n'
    + '2️⃣ ¿Qué día te gustaría pasar?\n'
    + '3️⃣ ¿Prefieres horario matutino (9am-1pm) o vespertino (2pm-6pm)?\n\n'
    + '📅 Horarios de atención:\n'
    + 'Lunes a viernes: 9:00 AM - 6:00 PM\n'
    + 'Sábados: 9:00 AM - 2:00 PM\n'
    + '📍 Calle Principal #123, Col. Centro';
}

return [
  {
    json: {
      telefono: telefono,
      mensaje: mensaje,
      respuesta: respuesta,
      categoria: 'AGENDAMIENTO',
      cliente_id: clienteId
    }
  }
];
